'use strict';
const {test,expect}=require('@playwright/test');
const {DungeonRuntime,shortestPath}=require('../../dist/games/ai-dungeon/src/index.js');
const fs=require('node:fs');fs.mkdirSync('artifacts',{recursive:true});

/**
 * Actual Three.js + original authority: the only fixture is a valid seeded
 * floor with guard and protagonist moved into a legal boss-court adjacency.
 * The AFTER is generated by the actual DungeonRuntime.step() attack, not
 * a painted overlay, invented screenshot or hand-written publicState.
 *
 * This controlled encounter is an integration audit, NOT the full organic
 * continuous-story reel or an independent Diablo IV comparison.
 */
function stagedRealSealBreak(){
 const game=DungeonRuntime.create('dungeon-warden-m1-browser-encounter');
 const s=game.state,boss=s.units.find(u=>u.kind==='warden'),hero=s.units.find(u=>u.id==='vanguard');
 const guard=s.units.find(u=>u.kind==='revenant');
 if(!boss||!hero||!guard)throw Error('Missing real authority actors');
 const path=shortestPath(s.map,hero,boss);
 if(path.length<4)throw Error('Seed did not provide a legal boss-court lane');
 for(const u of s.units)if(u.faction==='enemy'&&u!==boss)u.hp=0;
 hero.x=path[path.length-2].x;hero.z=path[path.length-2].z;
 guard.x=path[path.length-3].x;guard.z=path[path.length-3].z;guard.hp=1;
 const before=game.publicState();
 if(before.guardianWard!==true||before.defendersRemaining!==1)throw Error('Staged real binding-guard rules invalid');
 const after=game.step();
 if(after.guardianWard!==false||after.defendersRemaining!==0||
    !after.events.some(e=>e.kind==='unseal'&&e.tick===after.tick))
  throw Error('Real autonomous strike did not shatter the living binding seal');
 return {before,after};
}
test('real Three.js desktop and mobile show the authoritative Warden binding seal breaking',async({page,request})=>{
 test.setTimeout(180000);
 expect((await request.get('/dungeon')).status()).toBe(200);
 const {before,after}=stagedRealSealBreak();let current=before,errors=[];
 page.on('pageerror',e=>errors.push(String(e)));
 await page.route('**/dungeon/state',route=>route.fulfill({json:current}));
 await page.goto('/dungeon');
 await expect.poll(()=>page.evaluate(()=>window.__DUNGEON_RENDER_DIAGNOSTICS__?.webgl===true),{timeout:60000}).toBe(true);
 await expect.poll(()=>page.evaluate(()=>window.__DUNGEON_RENDER_DIAGNOSTICS__?.wardBarrierVisible),{timeout:45000}).toBe(true);
 await expect.poll(()=>page.evaluate(()=>window.__DUNGEON_RENDER_DIAGNOSTICS__?.wardenRitual?.activeTethers),{timeout:45000}).toBeGreaterThan(0);
 await expect(page.locator('#floor-status')).toContainText('BINDING GUARDS');
 await page.locator('#world').screenshot({path:'artifacts/dungeon-warden-seal-m1-desktop-before-webgl.png',timeout:90000});
 current=after;
 await expect.poll(()=>page.evaluate(()=>window.__DUNGEON_PUBLIC_STATE__?.tick),{timeout:30000}).toBe(after.tick);
 await expect.poll(()=>page.evaluate(()=>window.__DUNGEON_RENDER_DIAGNOSTICS__?.wardBarrierVisible),{timeout:45000}).toBe(false);
 await expect(page.locator('#floor-status')).toContainText('WARDEN EXPOSED');
 const diag=await page.evaluate(()=>window.__DUNGEON_RENDER_DIAGNOSTICS__);
 expect(diag.guardianWard).toBe(false);
 expect(diag.wardenRitual?.shieldActive).toBe(false);
 expect(diag.wardenRitual?.activeTethers).toBe(0);
 expect(diag.defendersRemaining).toBe(0);
 expect(diag.composition.visibleHeroes).toBeGreaterThan(0);
 await page.locator('#world').screenshot({path:'artifacts/dungeon-warden-seal-m1-desktop-after-webgl.png',timeout:90000});
 await page.setViewportSize({width:390,height:844});
 await expect.poll(()=>page.evaluate(()=>window.__DUNGEON_RENDER_DIAGNOSTICS__?.composition?.viewport?.width),{timeout:15000}).toBeGreaterThan(150);
 await page.locator('#world').screenshot({path:'artifacts/dungeon-warden-seal-m1-mobile-after-webgl.png',timeout:90000});
 expect(errors).toEqual([]);
 await test.info().attach('warden-seal-authority-and-renderer-receipt',{body:Buffer.from(JSON.stringify({
  seed:'dungeon-warden-m1-browser-encounter',provenance:'DungeonRuntime.create + staged legal positions + real DungeonRuntime.step',
  notOrganicFullCampaign:true,before:{tick:before.tick,guardianWard:before.guardianWard,defendersRemaining:before.defendersRemaining},
  after:{tick:after.tick,guardianWard:after.guardianWard,defendersRemaining:after.defendersRemaining,sealEvent:after.events.filter(e=>e.kind==='unseal')},
  renderer:{webgl:diag.webgl,wardBarrierVisible:diag.wardBarrierVisible,wardenRitual:diag.wardenRitual,
  composition:diag.composition,triangles:diag.triangles,drawCalls:diag.drawCalls}
 },null,2)),contentType:'application/json'});
});
